    BEQ R0, R0, L_bc_dd6b74ede14f4075b176e9d9ff0b77b3_16_77_done
L_bc_dd6b74ede14f4075b176e9d9ff0b77b3_16_77_use_stack:
    ADD T5, SB, R0
L_bc_dd6b74ede14f4075b176e9d9ff0b77b3_16_77_done:
    MOVE RV0, T0
    MOVE RV1, T5
; Jump to epilogue
    BEQ R0, R0, L_realloc_99999
L_realloc_99999:
; Return fat pointer
; === Function Epilogue ===
; Restore SP = FP
    ADD SP, FP, R0
; Restore callee-saved registers S3-S0
    ADDI SC, FP, -1
    LOAD S3, SB, SC
    ADDI SC, FP, -2
    LOAD S2, SB, SC
    ADDI SC, FP, -3
    LOAD S1, SB, SC
    ADDI SC, FP, -4
    LOAD S0, SB, SC
; Restore old FP
    ADDI SP, SP, -5
    LOAD FP, SB, SP
; Restore RAB
    ADDI SP, SP, -1
    LOAD RAB, SB, SP
; Restore RA
    ADDI SP, SP, -1
    LOAD RA, SB, SP
; Return to caller
    JALR R0, RAB, RA
